import { captureLocalReactPeers, } from "../../../platform/compat/react-paths.js";
import { isBun, isNode } from "../../../platform/compat/runtime.js";
import { getRuntimeModuleLoader } from "../../../platform/adapters/module-loader.js";
import { serverLogger } from "../../../utils/index.js";
import { buildAppRoutes, buildPagesRoutes } from "../static-generation.js";
import { createDependencyPinningSource, resolveDependencyPinningSnapshot, } from "../../../transforms/esm/package-registry.js";
const logger = serverLogger.component("build");
export async function executeBuild(pagesRoutes, appRoutes, options) {
    logger.debug(`[BUILD] executeBuild: ${pagesRoutes.length} pages routes, ${appRoutes.length} app routes`);
    const reactPeers = (isNode || isBun) && !getRuntimeModuleLoader(options.adapter)
        ? options.reactPeers ?? captureLocalReactPeers()
        : undefined;
    const dependencySnapshot = await resolveDependencyPinningSnapshot(createDependencyPinningSource({
        projectDir: options.projectDir,
        adapter: options.adapter,
        isLocalProject: options.isLocalProject,
        contentSourceId: "production-build",
        config: options.config,
    }), options.dependencyPinningCacheKey, options.dependencyPinningDependencies, options.dependencyPinningConfiguredVersions);
    const buildOptions = {
        ...options,
        reactPeers,
        dependencyPinningCacheKey: dependencySnapshot.cacheKey,
        dependencyPinningDependencies: dependencySnapshot.dependencies,
        dependencyPinningConfiguredVersions: dependencySnapshot.configuredVersions,
    };
    logger.debug("Building pages...");
    const pagesStats = await buildPagesRoutes(pagesRoutes, buildOptions);
    logger.debug(`pagesStats: ${pagesStats.pages} pages built`);
    const appStats = await buildAppRoutes(appRoutes, buildOptions);
    logger.debug(`appStats: ${appStats.pages} pages built`);
    return {
        pages: pagesStats.pages + appStats.pages,
        totalSize: pagesStats.totalSize + appStats.totalSize,
        ssgPaths: [...pagesStats.ssgPaths, ...appStats.ssgPaths],
    };
}
